from abc import ABC, abstractmethod


class ReportSink(ABC):
    @abstractmethod
    def write(self, text):
        """Receive CSV text."""
        raise NotImplementedError


class CsvBuffer(ReportSink):
    def __init__(self):
        self.parts = []

    def write(self, text):
        self.parts.append(text)

    def getvalue(self):
        return "".join(self.parts)


